    'gate.employeeQuestion': '¿Eres empleado/a, no el/la propietario/a?', 'gate.employeeBody': 'No hace falta que sigas los pasos: pide a tu jefe/a que te diga la Clave de API y la URL de la base de datos que él/ella configuró (las puede ver en Nube → "Cambiar la configuración de Firebase"), pégalas en el formulario de abajo y pulsa "Guardar y conectar". Listo.',
    'gate.cloudIntro': 'Cada negocio tiene su <strong>propio espacio en la nube</strong> (gratuito, de Google), separado del resto. Sirve para sincronizar tus dispositivos (camareros, cocina, TPV) y activar las reservas/pedidos online por QR.',
    'gate.seeFullGuide': '¿No tienes esos datos? Ver guía completa (para el propietario)',
    'gate.followSteps': 'Sigue estos pasos:', 'gate.shareWithEmployees': '¿Vas a compartir esto con empleados? Lee esto',
    'gate.businesses': 'Negocios', 'gate.setupCloud': 'Configura tu nube', 'gate.cloudStepLabel': 'Paso 2 de 3 — Conecta tu nube (≈10 minutos, una sola vez)',
    'gate.nt.step1Title': 'Crea una cuenta gratis en Netlify', 'gate.nt.step1Body': 'Abre <code>www.netlify.com</code> en otra pestaña y pulsa <strong>"Sign up"</strong>. Puedes entrar con tu cuenta de Google. Es gratis y no pide tarjeta.',
    'gate.nt.step2Title': 'Ten los dos archivos juntos en una carpeta', 'gate.nt.step2Body': 'En una carpeta de tu ordenador deja <strong>los dos archivos</strong> de GastroGoan: <code>index.html</code> y <code>reservagastrogoan.html</code>. <strong>No renombres</strong> ninguno de los dos.',
    'gate.nt.step3Title': 'Arrastra la carpeta a Netlify', 'gate.nt.step3Body': 'En Netlify, ve a <strong>"Sites"</strong> y arrastra tu carpeta al recuadro <strong>"Drag and drop your site output folder here"</strong> (o "Deploys" → "Deploy manually").',
    'gate.nt.step4Title': 'Copia la dirección que te da', 'gate.nt.step4Body': 'En unos segundos Netlify publica el sitio y te da una dirección tipo <code>https://tu-sitio.netlify.app</code>. Puedes cambiar el nombre en "Site settings" → "Change site name".',
    'gate.nt.step5Title': 'Abre SIEMPRE la app desde esa dirección', 'gate.nt.step5Body': 'A partir de ahora gestiona la app desde <code>https://tu-sitio.netlify.app</code>. Al llamarse index.html, se abre directamente. Solo así el QR de reservas y pedidos funcionará de verdad para tus clientes.',
    'gate.nt.goodTitle': '¡Bien!', 'gate.nt.hostedBody': 'Estás abriendo la app desde una dirección pública (<code>${host}</code>). El QR de reservas ya puede funcionar. Si es tu sitio de Netlify, ya está todo listo.',
    'gate.nt.notHostedBody': 'Ahora mismo estás abriendo la app <strong>desde un archivo local</strong>, no desde internet. Las reservas/pedidos por QR <strong>no funcionarán</strong> hasta que subas la app a Netlify y la abras desde su dirección pública.',
    'gate.nt.title': 'Sube tu app a internet', 'gate.nt.stepLabel': 'Paso 1 de 3 — Sube tu app a internet (≈5 minutos, una sola vez)',
    'gate.nt.explain': 'La app de gestión funciona abierta en tu navegador, pero el <strong>QR de reservas y pedidos online</strong> solo funciona si subes los dos archivos a un hosting público gratuito como <strong>Netlify</strong>. Tienes el tutorial completo en <strong>tutorial-netlify.html</strong> (junto a la app).',
    'gate.nt.doneBtn': 'Ya está subida — Continuar',
    'gate.apiKeyLabel': 'Clave de API (apiKey)', 'gate.dbUrlLabel': 'URL de la base de datos (databaseURL)', 'gate.saveAndConnect': 'Guardar y conectar',
    'gate.cloudModalTitle': 'Nube — Sincronización entre dispositivos', 'gate.needLicenseForCloud': 'Activa tu licencia de GastroGoan para conectar este dispositivo a la nube.',
    'gate.licenseActivatedFor': 'Licencia activada para', 'gate.tenMinutesIntro': 'Tardarás unos 10 minutos, una sola vez. Sigue la guía paso a paso y luego pega aquí los dos datos que te pida al final:',
    'gate.miniStep1': 'Crea un proyecto gratis en <code>console.firebase.google.com</code>', 'gate.miniStep2': 'Activa <strong>Realtime Database</strong>',
    'gate.miniStep3': 'Activa el inicio de sesión <strong>Anónimo</strong> en Authentication', 'gate.miniStep4': 'Pega las reglas de seguridad que te indica la guía',
    'gate.miniStep5': 'Copia tu <code>apiKey</code> y <code>databaseURL</code> y pégalos abajo',
    'gate.cloudConnected': 'Este negocio está conectado a su nube Firebase', 'gate.connectMoreDevices': 'Para conectar más dispositivos',
    'gate.connectMoreDevicesBody': '(móviles de camareros, tablet de cocina): instala GastroGoan en ese dispositivo y activa la misma clave de licencia (${key}). Se sincronizará solo, automáticamente, sin pasos adicionales.',
