    'help.assistant.placeholder': 'Escriu el teu dubte...',
    'help.assistant.welcome': 'Hola! 👋 Sóc l\'assistent de GastroGoan. Escriu el teu dubte (per exemple "com obro una taula" o "com afegeixo un extra") i t\'ajudo a l\'instant. També pots explorar tots els temes a la pestanya Temes, o escriure a suport des de Contacte.',
    'help.assistant.fallback': 'No he trobat una resposta exacta per a això. Prova a escriure-ho d\'una altra manera, fes un cop d\'ull a la pestanya <strong>Temes</strong>, o prem <strong>Contacte</strong> per escriure directament a suport.',
